// Accept only incoming text/captions for the Escape Towns instance.
const body = $input.first().json.body ?? $input.first().json;
const data = body.data ?? {};
const key = data.key ?? {};
const message = data.message ?? {};
if (body.event !== 'messages.upsert' || body.instance !== 'escapetowns') return [];
if (key.fromMe !== false) return [];
const remoteJid = key.remoteJid ?? '';
if (!/^[0-9]+@(s\.whatsapp\.net|lid)$/.test(remoteJid)) return [];
const messageText = message.conversation ?? message.extendedTextMessage?.text
  ?? message.imageMessage?.caption ?? message.buttonsResponseMessage?.selectedDisplayText
  ?? message.listResponseMessage?.title;
if (typeof messageText !== 'string' || !messageText.trim()) return [];
return [{ json: {
  senderPhone: remoteJid.split('@')[0], remoteJid,
  senderName: data.pushName || 'Customer', messageId: key.id,
  messageText: messageText.trim(), isGroup: false, instance: 'escapetowns'
} }];
